const TAU=Math.PI*2,dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
export function solids(a){const g=a.g;return [...g.enemies.filter(p=>p.state!=='jump'&&!p.thrown&&!p.held),...g.food.filter(p=>!p.slide),...g.bombs.filter(p=>!p.thrown&&!p.held),...g.projectiles.filter(p=>!p.dead&&!g.isFlying(p)),...a.relics.filter(p=>!p.carried&&!p.attached),...(g.knife?[g.knife]:[])];}
export function radius(a,p){return a.g.enemies.includes(p)?a.g.enemyRadius(p):a.hands.includes(p)?13:p.type==='ball'?13:10;}
export function moveSolid(a,p,to,amount,ignore=null){if(p.kind===10)return false;const g=a.g,r=radius(a,p),others=solids(a),angle=Math.atan2(to.y-p.y,to.x-p.x);for(const off of [0,.5,-.5,1,-1,1.5,-1.5]){const q={x:p.x+Math.cos(angle+off)*amount,y:p.y+Math.sin(angle+off)*amount};if(g.blocked(q,r))continue;let good=true;for(const o of others){if(o===p||o===ignore||o===p.target&&p.state==='windup')continue;const minimum=r+radius(a,o)+1;if(dist(q,o)<minimum&&dist(q,o)<dist(p,o)-.01){good=false;break;}}if(good){p.x=q.x;p.y=q.y;return true;}}return false;}
export function brainRoam(a,e,dt){const g=a.g,h=g.enemyTarget(e),cx=g.width/2,cy=g.height/2,mx=Math.min(150,g.width*.22),my=Math.min(130,g.height*.2);
 if(!e.roam||g.age>=e.roamAt||dist(e,e.roam)<25||g.blocked(e.roam,36)){const away=Math.atan2(cy-h.y,cx-h.x),r=Math.min(g.width,g.height)*.26;let best=null;for(let i=0;i<16;i++){const angle=away+(g.random()-.5)*Math.PI*1.5,p={x:Math.max(mx,Math.min(g.width-mx,cx+Math.cos(angle)*r)),y:Math.max(my,Math.min(g.height-my,cy+Math.sin(angle)*r))};if(!g.blocked(p,40)){best=p;break;}}e.roam=best||{x:cx,y:cy};e.roamAt=g.age+2.5+g.random()*2;}
 g.moveEnemy(e,e.roam,58,dt);
}
export function hammer(a,e,angle){const g=a.g,r=38+g.random()*252,from={x:e.x,y:e.y},to={x:Math.max(12,Math.min(g.width-12,e.x+Math.cos(angle)*r)),y:Math.max(12,Math.min(g.height-12,e.y+Math.sin(angle)*r))};g.projectiles.push({type:'hammer',volley:g.age,...from,from,to,born:g.age,duration:.7+g.random()*.25,owner:e});g.events.push({type:'hammer'});}
export function tornado(a,h,dt){const g=a.g,list=solids(a).filter(p=>p!==h.owner&&p.kind!==10&&!p.attached&&!p.held),strength=d=>420/(1+(d/170)**1.35);
 if(g.age>=h.until){if(!h.released){h.released=true;for(const p of list){const d=dist(p,h),angle=Math.atan2(p.y-h.y,p.x-h.x),speed=440+Math.max(0,180-d*.2);p.gust={vx:Math.cos(angle)*speed,vy:Math.sin(angle)*speed,until:g.age+1.2};if(g.bombs.includes(p))p.armed??=g.age;}const head=g.body[0],a=Math.atan2(head.y-h.y,head.x-h.x);g.attraction=null;g.knockback={vx:Math.cos(a)*240,vy:Math.sin(a)*240,until:g.age+.9};g.events.push({type:'blackhole-burst',x:h.x,y:h.y,radius:190});}return;}
 for(const p of list){const d=dist(p,h);if(d<25)continue;const angle=Math.atan2(p.y-h.y,p.x-h.x),orbit={x:h.x+Math.cos(angle+.5)*Math.min(d*.25,45),y:h.y+Math.sin(angle+.5)*Math.min(d*.25,45)};const before={x:p.x,y:p.y};moveSolid(a,p,orbit,Math.min(d-24,dt*strength(d)));if(p.from){const dx=p.x-before.x,dy=p.y-before.y;p.from.x+=dx;p.from.y+=dy;if(p.to){p.to.x+=dx;p.to.y+=dy;}}}
 for(let i=0;i<list.length;i++)for(let j=i+1;j<list.length;j++){const p=list[i],q=list[j],d=dist(p,q),min=radius(a,p)+radius(a,q)+1;if(d>=min)continue;const angle=d>.01?Math.atan2(q.y-p.y,q.x-p.x):i*2.4;moveSolid(a,p,{x:p.x-Math.cos(angle)*min,y:p.y-Math.sin(angle)*min},Math.min((min-d)/2+1,3),q);moveSolid(a,q,{x:q.x+Math.cos(angle)*min,y:q.y+Math.sin(angle)*min},Math.min((min-d)/2+1,3),p);}
 const head=g.body[0],d=dist(head,h),angle=Math.atan2(h.y-head.y,h.x-head.x),power=strength(d)*.3;g.attraction={vx:Math.cos(angle)*power,vy:Math.sin(angle)*power};if(d<22&&!g.invincible)g.fail('블랙홀에 휘말렸어요.');
}
export function gusts(a,dt){for(const p of solids(a)){if(!p.gust)continue;if(a.g.age>=p.gust.until){delete p.gust;continue;}const v=p.gust,before={x:p.x,y:p.y};moveSolid(a,p,{x:p.x+v.vx,y:p.y+v.vy},Math.hypot(v.vx,v.vy)*dt);if(p.from){const dx=p.x-before.x,dy=p.y-before.y;p.from.x+=dx;p.from.y+=dy;if(p.to){p.to.x+=dx;p.to.y+=dy;}}v.vx*=Math.exp(-3*dt);v.vy*=Math.exp(-3*dt);}}
export function thrown(a,p){const g=a.g,f=p.thrown;if(!f)return;const t=Math.min(1,(g.age-f.born)/.8);p.x=f.from.x+(f.to.x-f.from.x)*t;p.y=f.from.y+(f.to.y-f.from.y)*t;p.lift=Math.sin(t*Math.PI)*75;if(t>=1){delete p.thrown;p.lift=0;p.born=g.age-.9;}}
function moveHand(a,hand,to,amount){const k=hand.king,r=a.g.enemyRadius(k)+16,d=dist(hand,k);if(d<r){const a=Math.atan2(hand.y-k.y,hand.x-k.x);hand.x=k.x+Math.cos(a)*r;hand.y=k.y+Math.sin(a)*r;}const angle=Math.atan2(to.y-hand.y,to.x-hand.x);for(const off of [0,.55,-.55,1.1,-1.1,1.65,-1.65,Math.PI]){const q={x:hand.x+Math.cos(angle+off)*amount,y:hand.y+Math.sin(angle+off)*amount};if((q.x-k.x)*hand.side<2)continue;if(dist(q,k)<r&&dist(q,k)<=dist(hand,k))continue;hand.x=q.x;hand.y=q.y;return;}}
export function hands(a,dt){const g=a.g,age=g.age;
 for(const hand of [...a.hands]){const k=hand.king;if(!g.enemies.includes(k)){a.removeHand(hand);continue;}
  if(g.armed&&dist(g.blade(),hand)<24){a.removeHand(hand);g.consumeKnife();g.events.push({type:'defeat',...hand});continue;}
  const alive=p=>g.enemies.includes(p)||g.bombs.includes(p);let t=hand.target;if((dist(hand,k)>175||(t&&(dist(t,k)>175||(t.x-k.x)*hand.side<0)))&&hand.state!=='return'){if(t)t.held=false;hand.target=null;hand.state='return';t=null;}
  if(t&&!alive(t)){hand.target=null;hand.state='return';t=null;}
  if(hand.state==='windup'&&t){const progress=Math.min(1,(age-hand.born)/.55),desired={x:hand.from.x-Math.cos(hand.angle)*23*progress,y:hand.from.y-Math.sin(hand.angle)*23*progress};moveHand(a,hand,desired,Math.min(dist(hand,desired),180*dt));t.x=hand.x;t.y=hand.y+24;
   if(age>=hand.until){t.held=false;t.thrown={from:{x:t.x,y:t.y},to:hand.aim,born:age};if(g.bombs.includes(t))t.armed=null;hand.state='return';hand.target=null;hand.until=age+2.4;g.events.push({type:'throw'});}continue;}
  if(hand.state==='reach'&&t){const desired=hand.side===-1?{x:t.x,y:t.y-24}:t;hand.angle=Math.atan2(t.y-hand.y,t.x-hand.x);moveHand(a,hand,desired,Math.min(dist(hand,desired),155*dt));
   if(dist(hand,desired)<(hand.side===-1?5:radius(a,t)+14)){if(hand.side===-1){t.held=true;hand.state='windup';hand.born=age;hand.until=age+.55;hand.from={x:hand.x,y:hand.y};hand.aim=g.randomAim();hand.angle=Math.atan2(hand.aim.y-hand.y,hand.aim.x-hand.x);}else{t.enhanced=true;hand.state='return';hand.pointUntil=age+.45;hand.target=null;hand.until=age+2.8;g.events.push({type:'enhance'});}}
   else if(age>=hand.reachUntil){hand.state='return';hand.target=null;hand.until=age+.8;}continue;}
  const home={x:Math.max(16,Math.min(g.width-16,k.x+hand.side*65)),y:Math.max(16,Math.min(g.height-16,k.y+Math.sin(age*1.4+hand.side)*15))};moveHand(a,hand,home,Math.min(dist(hand,home),130*dt));if(hand.state==='return'){if(dist(hand,home)<5)hand.state='idle';else continue;}
  if(age>=hand.until){let pool=g.enemies.filter(o=>(o.kind<6||o.kind===11)&&!o.held&&!o.thrown&&dist(o,k)<165&&(o.x-k.x)*hand.side>=0);if(hand.side===-1)pool.push(...g.bombs.filter(b=>!b.held&&!b.thrown&&dist(b,k)<165&&(b.x-k.x)*hand.side>=0));else{pool=pool.filter(e=>!e.enhanced);if(!pool.length)pool=g.bombs.filter(b=>!b.enhanced&&!b.held&&!b.thrown&&dist(b,k)<165&&(b.x-k.x)*hand.side>=0);}
   pool.sort((p,q)=>{const priority=p.kind===11?1:0,other=q.kind===11?1:0;return priority-other||dist(p,hand)-dist(q,hand)});if(pool[0]){hand.target=pool[0];hand.state='reach';hand.reachUntil=age+3;}else hand.until=age+.7;}

 }
}
